  FROM jnpct."individual_pregnancy_anc_cluster_incharge" x
  JOIN jnpct."individual_pregnancy" e ON e.id = x.program_enrolment_id
  JOIN jnpct.individual i ON i.id = e.individual_id
  LEFT JOIN jnpct.address a ON a.id = i.address_id
  WHERE x.encounter_date_time IS NOT NULL AND e.enrolment_date_time IS NOT NULL;
